      out.write("  }\n");
      out.write("\n");
      out.write("  function moveUp(idx) {\n");
      out.write("    if (idx <= 0) return;\n");
      out.write("    const tmp = selected[idx - 1];\n");
      out.write("    selected[idx - 1] = selected[idx];\n");
      out.write("    selected[idx] = tmp;\n");
      out.write("    renderSelected();\n");
      out.write("    renderMapSelectedLayer();\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  function moveDown(idx) {\n");
      out.write("    if (idx >= selected.length - 1) return;\n");
      out.write("    const tmp = selected[idx + 1];\n");
      out.write("    selected[idx + 1] = selected[idx];\n");
      out.write("    selected[idx] = tmp;\n");
      out.write("    renderSelected();\n");
      out.write("    renderMapSelectedLayer();\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  function removeAt(idx) {\n");
      out.write("    const id = selected[idx].id;\n");
