      out.write("    if (chk) chk.checked = false;\n");
      out.write("    const stayChk = document.querySelector('.stayChk[data-id=\"' + id + '\"]');\n");
      out.write("    if (stayChk) stayChk.checked = false;\n");
      out.write("    renderSelected();\n");
      out.write("    renderMapSelectedLayer();\n");
      out.write("    \n");
      out.write("    // 삭제 후 리스트가 비어있으면 왼쪽 패널 닫기\n");
      out.write("    if(selected.length === 0) {\n");
