      out.write("  }\n");
      out.write("\n");
      out.write("  async function calcRoute() {\n");
      out.write("    if (selected.length < 2) {\n");
      out.write("      UIToast.show('경로 계산은 최소 2개 장소가 필요합니다.', { type: 'warning' });\n");
      out.write("      return;\n");
      out.write("    }\n");
      out.write("    const spotIds = selected.map(s => s.id).join(',');\n");
      out.write("    const url = ctx + '/plans/api/directions?spotIds=' + encodeURIComponent(spotIds);\n");
      out.write("\n");
      out.write("    const res = await fetch(url);\n");
      out.write("    if (!res.ok) {\n");
      out.write("      UIToast.show('경로 계산에 실패했습니다. 서버 로그를 확인해 주세요.', { type: 'error' });\n");
      out.write("      return;\n");
      out.write("    }\n");
      out.write("    const data = await res.json();\n");
      out.write("\n");
      out.write("    document.getElementById('totalDist').innerText = formatDistance(data.distanceM);\n");
      out.write("    document.getElementById('totalTime').innerText = formatDuration(data.durationSec);\n");
      out.write("\n");
      out.write("    routeLines.forEach(l => l.setMap(null));\n");
      out.write("    routeLines = [];\n");
      out.write("\n");
      out.write("    const grouped = groupByDay();\n");
      out.write("    Object.keys(grouped).forEach(day => {\n");
      out.write("      const arr = grouped[day];\n");
      out.write("      if (arr.length < 2) return;\n");
      out.write("      const path = arr.map(s => new kakao.maps.LatLng(s.lat, s.lng));\n");
      out.write("\n");
      out.write("      const polyline = new kakao.maps.Polyline({\n");
      out.write("        path: path,\n");
      out.write("        strokeWeight: 5,\n");
      out.write("        strokeColor: getColorByDay(day),\n");
      out.write("        strokeOpacity: 0.85\n");
      out.write("      });\n");
      out.write("      polyline.setMap(map);\n");
      out.write("      routeLines.push(polyline);\n");
      out.write("    });\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  function getColorByDay(day) {\n");
      out.write("    const colors = { 1: \"#ff1744\", 2: \"#2979ff\", 3: \"#00c853\", 4: \"#ff9100\", 5: \"#9c27b0\" };\n");
      out.write("    return colors[Number(day)] || \"#222\";\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  function groupByDay() {\n");
      out.write("    const map = {};\n");
      out.write("    selected.forEach(s => {\n");
      out.write("      if (!map[s.day]) map[s.day] = [];\n");
      out.write("      map[s.day].push(s);\n");
      out.write("    });\n");
      out.write("    return map;\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  function getCenter() {\n");
      out.write("    let lat = 0, lng = 0;\n");
      out.write("    selected.forEach(s => { lat += s.lat; lng += s.lng; });\n");
      out.write("    return { lat: lat / selected.length, lng: lng / selected.length };\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  async function loadNearbyStays() {\n");
      out.write("    if (selected.length === 0) {\n");
      out.write("      UIToast.show('먼저 장소를 1개 이상 선택해 주세요.', { type: 'warning' });\n");
      out.write("      return;\n");
      out.write("    }\n");
      out.write("    const center = getCenter();\n");
      out.write("    const url = ctx + '/plans/api/stays?lat=' + center.lat + '&lng=' + center.lng;\n");
      out.write("\n");
      out.write("    const res = await fetch(url);\n");
      out.write("    if (!res.ok) {\n");
      out.write("      UIToast.show('숙소 불러오기에 실패했습니다. 서버 로그를 확인해 주세요.', { type: 'error' });\n");
      out.write("      return;\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    const stays = await res.json();\n");
      out.write("    clearStayMarkers();\n");
      out.write("\n");
      out.write("    const stayList = document.getElementById('stayList');\n");
      out.write("    stayList.innerHTML = '';\n");
      out.write("\n");
      out.write("    if (!stays || stays.length === 0) {\n");
      out.write("      stayList.innerHTML = '<div class=\"muted\" style=\"padding:8px 0; text-align:center;\">근처 숙소가 없습니다.</div>';\n");
      out.write("      return;\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    stays.forEach(stay => {\n");
      out.write("      const id = Number(stay.id ?? stay.sIdx ?? stay.idx ?? stay.s_idx);\n");
      out.write("      const name = String(stay.name ?? stay.sName ?? stay.s_name ?? stay.spotName ?? stay.sname ?? '');\n");
      out.write("      const lat = Number(stay.lat ?? stay.sLat ?? stay.s_lat);\n");
      out.write("      const lng = Number(stay.lng ?? stay.sLng ?? stay.s_lng);\n");
      out.write("      const dist = Number(stay.distance ?? stay.dist ?? stay.distanceKm ?? stay.distance_km ?? 0);\n");
      out.write("\n");
      out.write("      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;\n");
      out.write("\n");
      out.write("      const row = document.createElement('div');\n");
      out.write("      row.className = 'row';\n");
      out.write("      const checked = false;// 기본은 체크 해제(선택한 숙소만 마커 표시)\n");
      out.write("\n");
      out.write("      row.innerHTML =\n");
      out.write("        '<label style=\"flex:1; cursor: pointer; display: flex; align-items: center;\">' +\n");
      out.write("          '<input type=\"checkbox\" class=\"stayChk\" ' +\n");
      out.write("	            'data-id=\"' + id + '\" data-name=\"' + escapeHtml(name) + '\" data-lat=\"' + lat + '\" data-lng=\"' + lng + '\" data-dist=\"' + dist + '\" ' +\n");
      out.write("            (checked ? 'checked' : '') + ' style=\"margin-right: 8px;\">' +\n");
      out.write("          escapeHtml(name) +\n");
      out.write("          '<span class=\"muted tiny\" style=\"margin-left:4px;\"> (약 ' + dist.toFixed(2) + ' km)</span>' +\n");
      out.write("        '</label>';\n");
      out.write("\n");
      out.write("	      stayList.appendChild(row);\n");
      out.write("    });\n");
      out.write("\n");
      out.write("	    // ✅ 체크된 숙소만 마커 표시\n");
      out.write("	    function syncStayMarker(chk){\n");
      out.write("	      const id = Number(chk.dataset.id);\n");
      out.write("	      if (!Number.isFinite(id)) return;\n");
      out.write("\n");
      out.write("	      if (chk.checked) {\n");
      out.write("	        if (stayMarkerById[id]) return; // 이미 표시 중\n");
      out.write("	        const lat = Number(chk.dataset.lat);\n");
      out.write("	        const lng = Number(chk.dataset.lng);\n");
      out.write("	        if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;\n");
      out.write("	        const name = chk.dataset.name || '숙소';\n");
      out.write("	        const dist = Number(chk.dataset.dist || 0);\n");
      out.write("\n");
      out.write("	        const marker = new kakao.maps.Marker({\n");
      out.write("	          position: new kakao.maps.LatLng(lat, lng),\n");
      out.write("	          map: map\n");
      out.write("	        });\n");
      out.write("	        stayMarkerById[id] = marker;\n");
      out.write("	        stayMarkers.push(marker);\n");
      out.write("\n");
      out.write("	        const iw = new kakao.maps.InfoWindow({\n");
      out.write("	          content: '<div style=\"padding:8px;\"><b>' + escapeHtml(name) + '</b>' +\n");
      out.write("	                   (Number.isFinite(dist) && dist > 0 ? ('<br>약 ' + dist.toFixed(2) + ' km') : '') +\n");
      out.write("	                   '</div>'\n");
      out.write("	        });\n");
      out.write("	        kakao.maps.event.addListener(marker, 'click', () => iw.open(map, marker));\n");
      out.write("	      } else {\n");
      out.write("	        const marker = stayMarkerById[id];\n");
      out.write("	        if (!marker) return;\n");
      out.write("	        marker.setMap(null);\n");
      out.write("	        delete stayMarkerById[id];\n");
      out.write("	        stayMarkers = stayMarkers.filter(m => m !== marker);\n");
      out.write("	      }\n");
      out.write("	    }\n");
      out.write("\n");
      out.write("	    document.querySelectorAll('.stayChk').forEach(chk => {\n");
      out.write("	      // 로드 직후: 체크된 숙소만 마커 표시\n");
      out.write("	      syncStayMarker(chk);\n");
      out.write("      chk.addEventListener('change', () => {\n");
      out.write("        const id = Number(chk.dataset.id);\n");
      out.write("	        // ✅ 마커는 체크 상태에 맞게만 표시/해제\n");
      out.write("	        syncStayMarker(chk);\n");
      out.write("        if (chk.checked) {\n");
      out.write("          if (selected.some(x => x.id === id)) return;\n");
      out.write("          selected.push({ id: id, name: chk.dataset.name + ' (숙소)', lat: Number(chk.dataset.lat), lng: Number(chk.dataset.lng), day: 1, memo: '숙소' });\n");
      out.write("          \n");
      out.write("          // 숙소 선택 시 왼쪽 패널 닫혀있으면 열기\n");
      out.write("          const leftPanel = document.getElementById('leftTimeline');\n");
      out.write("          if (leftPanel.classList.contains('closed')) {\n");
      out.write("            toggleLeftPanel();\n");
      out.write("          }\n");
      out.write("        } else {\n");
      out.write("          selected = selected.filter(x => x.id !== id);\n");
      out.write("        }\n");
      out.write("        renderSelected();\n");
      out.write("        renderMapSelectedLayer(); \n");
      out.write("        \n");
      out.write("        // 삭제 후 리스트가 비어있으면 왼쪽 패널 닫기\n");
      out.write("        if(selected.length === 0) {\n");
      out.write("            const leftPanel = document.getElementById('leftTimeline');\n");
      out.write("            if (!leftPanel.classList.contains('closed')) {\n");
      out.write("              toggleLeftPanel();\n");
      out.write("            }\n");
      out.write("        }\n");
      out.write("      });\n");
      out.write("    });\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  function savePlan() {\n");
      out.write("    if (selected.length < 1) {\n");
      out.write("      UIToast.show('저장할 장소가 없습니다.', { type: 'warning' });\n");
      out.write("      return;\n");
      out.write("    }\n");
      out.write("    buildHiddenInputs();\n");
      out.write("    document.getElementById('saveForm').submit();\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  function formatDuration(sec) {\n");
      out.write("    sec = Number(sec || 0);\n");
      out.write("    const h = Math.floor(sec / 3600);\n");
      out.write("    const m = Math.floor((sec % 3600) / 60);\n");
      out.write("    return (h > 0 ? (h + '시간 ') : '') + (m + '분');\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  function formatDistance(m) {\n");
      out.write("    m = Number(m || 0);\n");
      out.write("    return (m >= 1000) ? ((m / 1000).toFixed(1) + ' km') : (m + ' m');\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  function escapeHtml(str) { return String(str).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('\"','&quot;').replaceAll(\"'\",'&#039;'); }\n");
      out.write("  function escapeXml(str) { return String(str ?? '').replaceAll('&','&amp;').replaceAll('\"','&quot;').replaceAll(\"'\",'&#039;').replaceAll('<','&lt;').replaceAll('>','&gt;'); }\n");
      out.write("</script>\n");
      out.write("\n");
      out.write("\n");
